#include "mspa/diagnostics/trace.hpp"
#include <algorithm>
namespace mspa {std::uint64_t TraceSink::push(DiagnosticTrace t){t.token=next_++;if(max_==0)return t.token;if(traces_.size()>=max_)traces_.erase(traces_.begin(),traces_.begin()+static_cast<std::ptrdiff_t>(traces_.size()-max_+1));traces_.push_back(std::move(t));return traces_.back().token;}const std::vector<DiagnosticTrace>&TraceSink::traces()const noexcept{return traces_;}const DiagnosticTrace*TraceSink::find(std::uint64_t token)const noexcept{auto it=std::find_if(traces_.begin(),traces_.end(),[&](const auto&t){return t.token==token;});return it==traces_.end()?nullptr:&*it;}void TraceSink::clear()noexcept{traces_.clear();}void TraceSink::set_max(std::size_t m)noexcept{max_=m;if(traces_.size()>max_)traces_.erase(traces_.begin(),traces_.begin()+static_cast<std::ptrdiff_t>(traces_.size()-max_));}}
